test('RATES has correct currency values', () => {
  assert.equal(RATES.EUR, 1);
  assert.equal(RATES.USD, 1.085);
  assert.equal(RATES.GBP, 0.8425);
});

test('convert EUR to USD', () => {
  const r = convert(10000, 'USD');
  assert.equal(r.ok, true);
  assert.equal(r.value, 10850);
});

test('convert EUR to GBP', () => {
  const r = convert(10000, 'GBP');
  assert.equal(r.ok, true);
  assert.equal(r.value, 8425);
});

test('convert EUR to EUR (no change)', () => {
  const r = convert(10000, 'EUR');
  assert.equal(r.ok, true);
  assert.equal(r.value, 10000);
});

test('convert with rounding', () => {
  const r = convert(1, 'USD');
  assert.equal(r.ok, true);
  assert.equal(r.value, 1);
});

test('convert unknown currency returns fail', () => {
  const r = convert(10000, 'JPY');
  assert.equal(r.ok, false);
  assert.equal(r.error, 'UNKNOWN_CURRENCY');
});

test('convert zero cents', () => {
  const r = convert(0, 'USD');
  assert.equal(r.ok, true);
  assert.equal(r.value, 0);
});

test('convert fractional result rounds correctly', () => {
  const r = convert(333, 'USD');
  assert.equal(r.ok, true);
  assert.equal(r.value, 361);
});

test('convert preserves negative amounts', () => {
  const r = convert(-10000, 'USD');
  assert.equal(r.ok, true);
  assert.equal(r.value, -10850);
});

test('formatMoney EUR with euro sign and comma separator', () => {
  assert.equal(formatMoney(123456, 'EUR'), '€1,234.56');
  assert.equal(formatMoney(-5, 'EUR'), '-€0.05');
  assert.equal(formatMoney(100, 'EUR'), '€1.00');
  assert.equal(formatMoney(0, 'EUR'), '€0.00');
});

test('formatMoney USD with dollar sign', () => {
  assert.equal(formatMoney(123456, 'USD'), '$1,234.56');
  assert.equal(formatMoney(100, 'USD'), '$1.00');
  assert.equal(formatMoney(1, 'USD'), '$0.01');
  assert.equal(formatMoney(0, 'USD'), '$0.00');
});

test('formatMoney GBP with pound sign', () => {
  assert.equal(formatMoney(123456, 'GBP'), '£1,234.56');
  assert.equal(formatMoney(100, 'GBP'), '£1.00');
  assert.equal(formatMoney(1, 'GBP'), '£0.01');
  assert.equal(formatMoney(0, 'GBP'), '£0.00');
});

test('formatMoney with negative amounts', () => {
  assert.equal(formatMoney(-5, 'USD'), '-$0.05');
  assert.equal(formatMoney(-5, 'GBP'), '-£0.05');
  assert.equal(formatMoney(-100, 'EUR'), '-€1.00');
});

test('formatMoney with unknown currency', () => {
  const result = formatMoney(123456, 'JPY');
  assert.equal(result, 'Unknown Currency');
});

test('convert and format workflow EUR to USD', () => {
  const eurCents = 100000;
  const convertResult = convert(eurCents, 'USD');
  assert.equal(convertResult.ok, true);
  const usdCents = convertResult.value;
  const formatted = formatMoney(usdCents, 'USD');
  assert.equal(formatted, '$1,085.00');
});

test('convert and format workflow EUR to GBP', () => {
  const eurCents = 100000;
  const convertResult = convert(eurCents, 'GBP');
  assert.equal(convertResult.ok, true);
  const gbpCents = convertResult.value;
  const formatted = formatMoney(gbpCents, 'GBP');
  assert.equal(formatted, '£842.50');
});

test('formatMoney large amounts with multiple commas', () => {
  assert.equal(formatMoney(123456789, 'EUR'), '€1,234,567.89');
  assert.equal(formatMoney(123456789, 'USD'), '$1,234,567.89');
  assert.equal(formatMoney(123456789, 'GBP'), '£1,234,567.89');
});

test('convert multiple currencies from same amount', () => {
  const eur = 50000;
  const usd = convert(eur, 'USD');
  const gbp = convert(eur, 'GBP');

  assert.equal(usd.value, 54250);
  assert.equal(gbp.value, 42125);
});

